export function getResourceBySlug(slug: string) {
	return Object.values(adminResources).find((resource) => resource.slug === slug);
}

export function listResourceEntries() {
	return Object.values(adminResources).sort((a, b) => a.name.localeCompare(b.name));
}

export function resourceDisplayName(name: string): string {
	return name.replace(/([a-z0-9])([A-Z])/g, "$1 $2");
}

export function resourcePluralLabel(name: string): string {
	const base = resourceDisplayName(name);
	const parts = base.split(" ");
	const last = parts[parts.length - 1] ?? base;
	const plural = /[^aeiou]y$/i.test(last)
		? last.slice(0, -1) + "ies"
		: /(s|x|z|ch|sh)$/i.test(last)
			? last + "es"
			: last + "s";
	parts[parts.length - 1] = plural;
	return parts.join(" ");
}
